const meta = {
  parameters: {
    docs: {
      description: {
        component: "## Usage

Build accessible panel groups and layouts that can be resized with the keyboard.

**Import:** `@/registry/erbium/ui/resizable`

## About

The `Resizable` component is built on top of [react-resizable-panels](https://github.com/bvaughn/react-resizable-panels) by [bvaughn](https://github.com/bvaughn).

## Usage

```tsx
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/registry/erbium/ui/resizable";
```

```tsx
<ResizablePanelGroup orientation="horizontal">
  <ResizablePanel>One</ResizablePanel>
  <ResizableHandle />
  <ResizablePanel>Two</ResizablePanel>
</ResizablePanelGroup>
```

## Composition

Use the following composition to build a `ResizablePanelGroup`:

```text
ResizablePanelGroup
├── ResizablePanel
├── ResizableHandle
└── ResizablePanel
```

## Changelog

Updated to `react-resizable-panels` v4. See the [v4.0.0 release notes](https://github.com/bvaughn/react-resizable-panels/releases/tag/4.0.0) for full details.

If you're using `react-resizable-panels` primitives directly, note the following changes:

| v3                           | v4                      |
| ---------------------------- | ----------------------- |
| `PanelGroup`                 | `Group`                 |
| `PanelResizeHandle`          | `Separator`             |
| `direction` prop             | `orientation` prop      |
| `defaultSize={50}`           | `defaultSize="50%"`     |
| `onLayout`                   | `onLayoutChange`        |
| `ImperativePanelHandle`      | `PanelImperativeHandle` |
| `ref` prop on Panel          | `panelRef` prop         |
| `data-panel-group-direction` | `aria-orientation`      |

The Shadcn/ui wrapper components (`ResizablePanelGroup`, `ResizablePanel`,

`ResizableHandle`) remain unchanged.

## External documentation

react-resizable-panels supplies the panel groups, panels, and resize separators.

- [react-resizable-panels](https://react-resizable-panels.vercel.app)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta;

export default { ...meta, title: "Components/Resizable",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  orientation: "horizontal" | "vertical";
  firstPanelSize: number;
  showHandle: boolean;
}> = {
  argTypes: {
    firstPanelSize: { control: { max: 90, min: 10, step: 5, type: "range" } },
    orientation: { control: "select", options: ["horizontal", "vertical"] },
    showHandle: { control: "boolean" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import {
  ResizablePanel,
  ResizableHandle,
  ResizablePanelGroup,
} from "@/registry/erbium/ui/resizable";

export const defaultProps = {
  firstPanelSize: 50,
  orientation: "horizontal",
  showHandle: true,
} satisfies {
  orientation: "horizontal" | "vertical";
  firstPanelSize: number;
  showHandle: boolean;
};

export default function ResizablePlaygroundExample(
  args: {
    orientation: "horizontal" | "vertical";
    firstPanelSize: number;
    showHandle: boolean;
  } = defaultProps,
) {
  return (
    <ResizablePanelGroup
      key={`${args.orientation}-${args.firstPanelSize}`}
      orientation={args.orientation}
      className="h-48 w-80 rounded-xl border surface-panel"
    >
      <ResizablePanel
        defaultSize={`${args.firstPanelSize}%`}
        className="flex items-center justify-center"
      >
        First
      </ResizablePanel>
      <ResizableHandle withHandle={args.showHandle} />
      <ResizablePanel
        defaultSize={`${100 - args.firstPanelSize}%`}
        className="flex items-center justify-center"
      >
        Second
      </ResizablePanel>
    </ResizablePanelGroup>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

